WITH valid AS (SELECT id, store_name, city, region, opened_date, sqft, LENGTH(city) AS city_length, COALESCE(region, 'UNKNOWN') AS region_clean FROM stores WHERE sqft BETWEEN 5421 AND 5496), metrics AS (SELECT id, store_name, region, opened_date, NTILE(3) OVER (PARTITION BY region ORDER BY sqft DESC, id) AS sqft_bucket, DENSE_RANK() OVER (ORDER BY sqft DESC) AS sqft_dense_rank FROM valid), matched_keys AS (SELECT id FROM metrics EXCEPT SELECT id FROM stores WHERE sqft BETWEEN 4594 AND 6447), verified AS (SELECT s.* FROM metrics s INNER JOIN matched_keys k ON s.id = k.id), filtered AS (SELECT id, store_name, opened_date, sqft_bucket, sqft_bucket + sqft_dense_rank AS sqft_bucket_plus_sqft_dense_rank, COALESCE(region, 'UNKNOWN') AS resolved_region FROM verified WHERE region IS DISTINCT FROM 'North') SELECT CASE WHEN sqft_bucket_plus_sqft_dense_rank >= 75 THEN 'PREMIUM' ELSE 'STANDARD' END AS sqft_bucket_plus_sqft_dense_rank_tier, COUNT(*) AS row_count, APPROX_PERCENTILE(sqft_bucket_plus_sqft_dense_rank, ARRAY(0.25, 0.5, 0.75)) AS sqft_bucket_plus_sqft_dense_rank_quartiles FROM filtered GROUP BY sqft_bucket_plus_sqft_dense_rank_tier HAVING row_count > 1 ORDER BY row_count DESC NULLS LAST;
